    expect count_in_range(1_u32, 4_u32, 1_u32) == 4_u32
}

test "count_in_range: 2 to 6 step 2 = 3" {
    expect count_in_range(2_u32, 6_u32, 2_u32) == 3_u32
}

test "count_in_range: 0 to 10 step 1 = 11" {
    expect count_in_range(0_u32, 10_u32, 1_u32) == 11_u32
}

test "count_in_range: 0 to 9 step 3 = 4" {
    expect count_in_range(0_u32, 9_u32, 3_u32) == 4_u32
}

test "count_in_range: 1 to 1 step 5 = 1" {
    expect count_in_range(1_u32, 1_u32, 5_u32) == 1_u32
}

test "count_in_range: 5 to 15 step 5 = 3" {
    expect count_in_range(5_u32, 15_u32, 5_u32) == 3_u32
